export const envelope = [15, 32, 23];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 8; // Nominal ground level

  // Extract theme wood and stone palettes with robust fallbacks
  const woodPlanks = api.theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood?.log || "minecraft:dark_oak_log";
  const woodStripped = api.theme.wood?.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme.wood?.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = api.theme.wood?.slab || "minecraft:dark_oak_slab";
  const woodFence = api.theme.wood?.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme.wood?.trapdoor || "minecraft:spruce_trapdoor";

  const stonePlinth = api.theme.ground?.plinth || api.theme.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone?.accent || "minecraft:smooth_stone";

  // Helper to append/replace block states safely
  function withState(block, state) {
    if (!block) return "minecraft:oak_planks";
    const base = block.split("[")[0];
    return `${base}[${state}]`;
  }

  // 3D Voxel buffer for deterministic geometric composition
  const grid = [];
  for (let x = 0; x < W; x++) {
    grid[x] = [];
    for (let y = 0; y < H; y++) {
      grid[x][y] = new Array(D).fill(null);
    }
  }

  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // Track occupied base columns for ground conformation (Rule 6)
  const footprint = new Map(); // key "x,z" => true
  function markFootprint(x, z) {
    footprint.set(`${x},${z}`, true);
  }

  // --------------------------------------------------------------------------
  // 1. SLED PLATFORM & WHEELS (Seat plane Y = 8 to 10)
  // --------------------------------------------------------------------------

  // Longitudinal Skid Runners (X = 2..3 and X = 11..12, Z = 1..21)
  for (let z = 1; z <= 21; z++) {
    for (let x of [2, 3, 11, 12]) {
      markFootprint(x, z);
      set(x, seatY, z, withState(woodLog, "axis=z"));
      set(x, seatY + 1, z, withState(woodLog, "axis=z"));
    }
  }

  // Upturned front & back sled runner horns
  set(2, seatY + 1, 1, withState(woodStairs, "facing=south,half=bottom"));
  set(3, seatY + 1, 1, withState(woodStairs, "facing=south,half=bottom"));
  set(11, seatY + 1, 1, withState(woodStairs, "facing=south,half=bottom"));
  set(12, seatY + 1, 1, withState(woodStairs, "facing=south,half=bottom"));

  set(2, seatY + 1, 21, withState(woodStairs, "facing=north,half=bottom"));
  set(3, seatY + 1, 21, withState(woodStairs, "facing=north,half=bottom"));
  set(11, seatY + 1, 21, withState(woodStairs, "facing=north,half=bottom"));
  set(12, seatY + 1, 21, withState(woodStairs, "facing=north,half=bottom"));

  // Heavy transverse cross-ties
  const tieZ = [2, 6, 11, 16, 20];
  for (const z of tieZ) {
    for (let x = 2; x <= 12; x++) {
      markFootprint(x, z);
      set(x, seatY + 1, z, withState(woodLog, "axis=x"));
    }
  }

  // Heavy Wheel Axles at Z = 6 and Z = 16
  for (const z of [6, 16]) {
    for (let x = 0; x <= 14; x++) {
      set(x, seatY + 1, z, withState(woodLog, "axis=x"));
    }
    // Linchpins / Hub caps
    set(0, seatY + 1, z, withState(woodTrapdoor, "facing=west,half=bottom,open=false"));
    set(14, seatY + 1, z, withState(woodTrapdoor, "facing=east,half=bottom,open=false"));
  }

  // 4 Massive Solid Timber Wheels (Centers at X = 1 & 13, Z = 6 & 16, Y = seatY + 1)
  const wheelHubs = [
    [1, 6], [13, 6], [1, 16], [13, 16]
  ];

  for (const [wx, wz] of wheelHubs) {
    // Wheel footprint columns
    for (let dz = -2; dz <= 2; dz++) {
      markFootprint(wx, wz + dz);
      if (wx === 1) markFootprint(wx + 1, wz + dz);
      if (wx === 13) markFootprint(wx - 1, wz + dz);
    }

    // Wheel discs
    for (let dz = -2; dz <= 2; dz++) {
      for (let dy = -1; dy <= 2; dy++) {
        const y = seatY + 1 + dy;
        const distSq = dz * dz + dy * dy;
        if (distSq <= 4.4) {
          set(wx, y, wz + dz, woodPlanks);
        }
      }
    }

    // Wheel rim contouring
    const cy = seatY + 1;
    set(wx, cy + 2, wz, withState(woodSlab, "type=bottom"));
    set(wx, cy - 1, wz, woodPlanks);
    set(wx, cy, wz - 2, withState(woodStairs, "facing=south,half=bottom"));
    set(wx, cy, wz + 2, withState(woodStairs, "facing=north,half=bottom"));

    set(wx, cy + 1, wz - 1, withState(woodStairs, "facing=south,half=top"));
    set(wx, cy + 1, wz + 1, withState(woodStairs, "facing=north,half=top"));
    set(wx, cy - 1, wz - 1, withState(woodStairs, "facing=south,half=bottom"));
    set(wx, cy - 1, wz + 1, withState(woodStairs, "facing=north,half=bottom"));

    // Hub center
    set(wx, cy, wz, withState(woodStripped, "axis=x"));
  }

  // Sled Deck (Y = seatY + 2 = 10)
  for (let z = 2; z <= 20; z++) {
    for (let x = 3; x <= 11; x++) {
      markFootprint(x, z);
      set(x, seatY + 2, z, woodPlanks);
    }
  }

  // Deck rim wales & hauling cleats
  for (let z = 2; z <= 20; z++) {
    set(3, seatY + 2, z, withState(woodLog, "axis=z"));
    set(11, seatY + 2, z, withState(woodLog, "axis=z"));
  }
  // Corner hauling posts & rope anchors
  set(3, seatY + 3, 2, woodFence);
  set(11, seatY + 3, 2, woodFence);
  set(3, seatY + 3, 20, woodFence);
  set(11, seatY + 3, 20, woodFence);
  set(7, seatY + 3, 2, woodFence); // Central hitch

  // --------------------------------------------------------------------------
  // 2. THE 4 COLOSSAL LEGS (Y = 10 to 18)
  // --------------------------------------------------------------------------

  const legDefs = [
    { name: "fl", xMin: 4, xMax: 5, zMin: 6, zMax: 8, isFront: true },
    { name: "fr", xMin: 9, xMax: 10, zMin: 6, zMax: 8, isFront: true },
    { name: "hl", xMin: 4, xMax: 5, zMin: 15, zMax: 17, isFront: false },
    { name: "hr", xMin: 9, xMax: 10, zMin: 15, zMax: 17, isFront: false }
  ];

  for (const leg of legDefs) {
    // Hoof / Footing (Y = 10..11)
    for (let x = leg.xMin; x <= leg.xMax; x++) {
      for (let z = leg.zMin; z <= leg.zMax; z++) {
        set(x, 10, z, withState(woodLog, "axis=y"));
        set(x, 11, z, withState(woodStripped, "axis=y"));
      }
    }

    // Hoof flare stairs
    const facingOuter = leg.xMin < 7 ? "facing=east" : "facing=west";
    const outerX = leg.xMin < 7 ? leg.xMin - 1 : leg.xMax + 1;
    for (let z = leg.zMin; z <= leg.zMax; z++) {
      set(outerX, 10, z, withState(woodStairs, `${facingOuter},half=bottom`));
    }
    if (leg.isFront) {
      set(leg.xMin, 10, leg.zMin - 1, withState(woodStairs, "facing=south,half=bottom"));
      set(leg.xMax, 10, leg.zMin - 1, withState(woodStairs, "facing=south,half=bottom"));
    } else {
      set(leg.xMin, 10, leg.zMax + 1, withState(woodStairs, "facing=north,half=bottom"));
      set(leg.xMax, 10, leg.zMax + 1, withState(woodStairs, "facing=north,half=bottom"));
    }

    // Cannon bone (Y = 12..14)
    for (let y = 12; y <= 14; y++) {
      for (let x = leg.xMin; x <= leg.xMax; x++) {
        for (let z = leg.zMin; z <= leg.zMin + 1; z++) {
          set(x, y, z, withState(woodLog, "axis=y"));
        }
      }
      // Rear tendon brace
      set(leg.xMin, y, leg.zMin + 2, woodFence);
      set(leg.xMax, y, leg.zMin + 2, woodFence);
    }

    // Joint: Knee (Front) or Hock (Rear) at Y = 15
    for (let x = leg.xMin; x <= leg.xMax; x++) {
      for (let z = leg.zMin; z <= leg.zMax; z++) {
        set(x, 15, z, withState(woodStripped, "axis=y"));
      }
    }
    if (!leg.isFront) {
      // Hock backward point
      set(leg.xMin, 15, leg.zMax + 1, withState(woodStairs, "facing=north,half=top"));
      set(leg.xMax, 15, leg.zMax + 1, withState(woodStairs, "facing=north,half=top"));
    }

    // Thigh / Upper Shoulder (Y = 16..17)
    for (let y = 16; y <= 17; y++) {
      const zOffset = leg.isFront ? -1 : 0;
      for (let x = leg.xMin - 1; x <= leg.xMax + 1; x++) {
        if (x >= 3 && x <= 11) {
          for (let z = leg.zMin + zOffset; z <= leg.zMax; z++) {
            set(x, y, z, woodPlanks);
          }
        }
      }
    }

    // Diagonal Ship Knee Braces from Leg to Deck
    const braceX = leg.xMin < 7 ? leg.xMax + 1 : leg.xMin - 1;
    set(braceX, 11, leg.zMin, withState(woodStairs, `${facingOuter},half=bottom`));
    set(braceX, 12, leg.zMin, withState(woodStairs, `${facingOuter},half=top`));
  }

  // --------------------------------------------------------------------------
  // 3. TORSO / BELLY / FLANKS (Y = 17 to 24, Z = 5 to 19, X = 2 to 12)
  // --------------------------------------------------------------------------

  // Sculpt outer hull using an ellipsoid with tapered flanks
  const cx = 7, cy = 20.5, cz = 12;
  const rx = 4.8, ry = 3.9, rz = 6.8;

  for (let x = 2; x <= 12; x++) {
    for (let y = 17; y <= 24; y++) {
      for (let z = 5; z <= 19; z++) {
        const dx = (x - cx) / rx;
        const dy = (y - cy) / ry;
        const dz = (z - cz) / rz;
        const distSq = dx * dx + dy * dy + dz * dz;

        if (distSq <= 1.08) {
          set(x, y, z, woodPlanks);
        }
      }
    }
  }

  // Horizontal ship wales / structural strakes around the hull
  for (let z = 6; z <= 18; z++) {
    for (let x of [2, 3, 11, 12]) {
      if (get(x, 19, z) === woodPlanks) set(x, 19, z, withState(woodLog, "axis=z"));
      if (get(x, 22, z) === woodPlanks) set(x, 22, z, withState(woodStripped, "axis=z"));
    }
  }

  // Decorative bronze/iron timber plates along flank
  for (const z of [9, 12, 15]) {
    set(2, 20, z, withState(woodTrapdoor, "facing=west,half=bottom,open=false"));
    set(12, 20, z, withState(woodTrapdoor, "facing=east,half=bottom,open=false"));
  }

  // Narrow spy-slits for concealed Greek warriors
  for (const z of [10, 14]) {
    set(2, 20, z, "minecraft:air");
    set(2, 21, z, withState(woodStairs, "facing=west,half=top"));
    set(12, 20, z, "minecraft:air");
    set(12, 21, z, withState(woodStairs, "facing=east,half=top"));
  }

  // --------------------------------------------------------------------------
  // 4. HOLLOW INTERIOR CHAMBER (The Soldier Hold: X: 4..10, Y: 18..21, Z: 8..16)
  // --------------------------------------------------------------------------

  // Hollow out the standable volume inside the hull
  for (let x = 4; x <= 10; x++) {
    for (let y = 18; y <= 21; y++) {
      for (let z = 8; z <= 16; z++) {
        set(x, y, z, "minecraft:air");
      }
    }
  }

  // Ensure solid floor under standable space
  for (let x = 4; x <= 10; x++) {
    for (let z = 8; z <= 16; z++) {
      set(x, 17, z, woodPlanks);
    }
  }

  // Internal curved ship frames / timber ribs
  for (const rz of [9, 11, 13, 15]) {
    // Rib columns along walls
    for (let y = 18; y <= 21; y++) {
      set(4, y, rz, withState(woodLog, "axis=y"));
      set(10, y, rz, withState(woodLog, "axis=y"));
    }
    // Overhead rib arches
    for (let x = 4; x <= 10; x++) {
      set(x, 22, rz, withState(woodLog, "axis=x"));
    }
  }

  // Interior soldier seating benches along the hull ribs
  for (let z = 9; z <= 15; z++) {
    if (get(4, 18, z) === "minecraft:air") {
      set(4, 18, z, withState(woodStairs, "facing=east,half=bottom"));
    }
    if (get(10, 18, z) === "minecraft:air") {
      set(10, 18, z, withState(woodStairs, "facing=west,half=bottom"));
    }
  }

  // Concealed belly exit trapdoors
  set(7, 17, 12, withState(woodTrapdoor, "facing=north,half=top,open=false"));
  set(6, 17, 12, withState(woodTrapdoor, "facing=north,half=top,open=false"));

  // Rolled rope ladder hanging down from belly exit towards deck
  for (let y = 11; y <= 16; y++) {
    set(7, y, 12, woodFence);
  }
  // Internal access ladder to climb up from hatch
  for (let y = 18; y <= 21; y++) {
    set(5, y, 12, "minecraft:ladder[facing=east]");
  }

  // --------------------------------------------------------------------------
  // 5. CHEST, WITHERS & NECK (Y = 18 to 28, Z = 2 to 9)
  // --------------------------------------------------------------------------

  // Muscular Chest (Z = 4..7, Y = 18..24)
  for (let y = 18; y <= 23; y++) {
    for (let x = 4; x <= 10; x++) {
      set(x, y, 4, woodPlanks);
      set(x, y, 5, woodPlanks);
    }
  }
  // Rounded breast curvature facing North
  for (let x = 5; x <= 9; x++) {
    set(x, 19, 3, withState(woodStairs, "facing=south,half=bottom"));
    set(x, 20, 3, withState(woodStairs, "facing=south,half=bottom"));
    set(x, 21, 3, woodPlanks);
    set(x, 22, 3, withState(woodStairs, "facing=south,half=top"));
  }

  // Dedicated Votive Plaque to Athena on chest
  set(6, 21, 3, stoneAccent);
  set(7, 21, 3, stoneAccent);
  set(8, 21, 3, stoneAccent);

  // Withers (Y = 24..25, Z = 7..9)
  for (let z = 7; z <= 9; z++) {
    for (let x = 5; x <= 9; x++) {
      set(x, 24, z, woodStripped);
    }
    set(7, 25, z, withState(woodStairs, "facing=south,half=bottom"));
  }

  // Neck slices angling forward & upward
  const neckSlices = [
    { y: 22, zMin: 4, zMax: 7, xMin: 5, xMax: 9 },
    { y: 23, zMin: 3, zMax: 6, xMin: 5, xMax: 9 },
    { y: 24, zMin: 3, zMax: 6, xMin: 5, xMax: 9 },
    { y: 25, zMin: 2, zMax: 5, xMin: 5, xMax: 9 },
    { y: 26, zMin: 2, zMax: 5, xMin: 5, xMax: 9 },
    { y: 27, zMin: 2, zMax: 4, xMin: 5, xMax: 9 },
    { y: 28, zMin: 2, zMax: 4, xMin: 5, xMax: 9 }
  ];

  for (const slice of neckSlices) {
    for (let z = slice.zMin; z <= slice.zMax; z++) {
      for (let x = slice.xMin; x <= slice.xMax; x++) {
        set(x, slice.y, z, woodStripped);
      }
    }
    // Under-throat smooth inverted stairs
    for (let x = slice.xMin + 1; x <= slice.xMax - 1; x++) {
      set(x, slice.y, slice.zMin, withState(woodStairs, "facing=north,half=top"));
    }
  }

  // Carved Crest & Flowing Mane along back of neck
  const maneSpine = [
    { y: 25, z: 8 },
    { y: 26, z: 7 },
    { y: 27, z: 6 },
    { y: 28, z: 5 },
    { y: 29, z: 4 },
    { y: 30, z: 3 }
  ];

  for (const m of maneSpine) {
    set(7, m.y, m.z, withState(woodStairs, "facing=south,half=bottom"));
    set(6, m.y - 1, m.z, withState(woodStairs, "facing=west,half=top"));
    set(8, m.y - 1, m.z, withState(woodStairs, "facing=east,half=top"));
  }

  // --------------------------------------------------------------------------
  // 6. HEAD, MUZZLE, JAW & EARS (Y = 25 to 30, Z = 0 to 4)
  // --------------------------------------------------------------------------

  // Skull & Forehead (Y = 27 to 29, Z = 1 to 4)
  for (let y = 27; y <= 28; y++) {
    for (let z = 1; z <= 3; z++) {
      for (let x = 6; x <= 8; x++) {
        set(x, y, z, woodStripped);
      }
    }
  }

  // Crown
  set(6, 29, 2, woodPlanks);
  set(7, 29, 2, woodPlanks);
  set(8, 29, 2, woodPlanks);
  set(7, 29, 1, withState(woodStairs, "facing=south,half=bottom"));

  // Masseter Cheeks & Eye sockets
  set(5, 27, 2, withState(woodStairs, "facing=east,half=bottom"));
  set(5, 27, 3, withState(woodStairs, "facing=east,half=bottom"));
  set(9, 27, 2, withState(woodStairs, "facing=west,half=bottom"));
  set(9, 27, 3, withState(woodStairs, "facing=west,half=bottom"));

  // Eye Sockets (dark recessed wood)
  set(5, 28, 2, withState(woodTrapdoor, "facing=west,half=bottom,open=false"));
  set(9, 28, 2, withState(woodTrapdoor, "facing=east,half=bottom,open=false"));

  // Muzzle Bridge (Y = 27, Z = 0..1)
  set(6, 27, 0, withState(woodStairs, "facing=south,half=bottom"));
  set(7, 27, 0, withState(woodStairs, "facing=south,half=bottom"));
  set(8, 27, 0, withState(woodStairs, "facing=south,half=bottom"));

  // Flared Nostrils & Snout Tip (Y = 26, Z = 0)
  set(6, 26, 0, withState(woodStairs, "facing=east,half=bottom"));
  set(7, 26, 0, woodStripped);
  set(8, 26, 0, withState(woodStairs, "facing=west,half=bottom"));

  // Lower Jaw / Chin (Y = 25, Z = 0..1)
  set(6, 25, 0, withState(woodStairs, "facing=south,half=top"));
  set(7, 25, 0, withState(woodStairs, "facing=south,half=top"));
  set(8, 25, 0, withState(woodStairs, "facing=south,half=top"));
  set(7, 25, 1, withState(woodStairs, "facing=south,half=top"));

  // Pricked Ears (Y = 29..30, Z = 3)
  // Left Ear
  set(5, 29, 3, withState(woodStairs, "facing=south,half=bottom"));
  set(5, 30, 3, withState(woodSlab, "type=bottom"));
  // Right Ear
  set(9, 29, 3, withState(woodStairs, "facing=south,half=bottom"));
  set(9, 30, 3, withState(woodSlab, "type=bottom"));

  // --------------------------------------------------------------------------
  // 7. RUMP, CROUP & BRAIDED TAIL (Y = 13 to 24, Z = 16 to 21)
  // --------------------------------------------------------------------------

  // Rump Slope
  for (let x = 4; x <= 10; x++) {
    set(x, 23, 17, woodPlanks);
    set(x, 23, 18, woodPlanks);
    set(x, 22, 19, withState(woodStairs, "facing=north,half=bottom"));
  }

  // Tail Root / Dock (Z = 19..20, Y = 22..23)
  set(7, 22, 19, withState(woodLog, "axis=z"));
  set(7, 23, 19, withState(woodStairs, "facing=north,half=bottom"));
  set(7, 22, 20, withState(woodLog, "axis=z"));
  set(7, 23, 20, withState(woodStairs, "facing=north,half=bottom"));

  // Tail Cascade (Y = 13 to 21, Z = 20..21)
  // Upper plume
  set(7, 21, 21, withState(woodLog, "axis=y"));
  set(6, 21, 21, woodFence);
  set(8, 21, 21, woodFence);

  set(7, 20, 21, withState(woodLog, "axis=y"));
  set(6, 20, 21, withState(woodStairs, "facing=west,half=bottom"));
  set(8, 20, 21, withState(woodStairs, "facing=east,half=bottom"));

  set(7, 19, 21, withState(woodLog, "axis=y"));
  set(7, 18, 21, withState(woodLog, "axis=y"));
  set(7, 17, 21, withState(woodLog, "axis=y"));

  // Mid & lower tresses
  set(6, 18, 21, woodFence);
  set(8, 18, 21, woodFence);
  set(7, 16, 21, woodFence);
  set(7, 15, 20, woodFence);
  set(7, 14, 20, woodFence);
  set(7, 13, 20, withState(woodSlab, "type=bottom"));

  // --------------------------------------------------------------------------
  // 8. TERRAIN CONFORMANCE (Rule 6)
  // --------------------------------------------------------------------------
  // For every occupied footprint column, build timber shoring / stone cribbing
  // down to the real ground heightAt(x, z).

  for (const key of footprint.keys()) {
    const [xStr, zStr] = key.split(",");
    const x = parseInt(xStr, 10);
    const z = parseInt(zStr, 10);

    const terrainH = Math.floor(api.heightAt(x, z));
    const targetY = seatY + terrainH;

    if (targetY < seatY) {
      // Ground drops away: build cribbing downward from seatY
      for (let y = Math.max(0, targetY); y < seatY; y++) {
        // Use logs along runners/axles, stone plinth along outer rim
        if (x === 2 || x === 3 || x === 11 || x === 12) {
          set(x, y, z, withState(woodLog, "axis=y"));
        } else {
          set(x, y, z, stonePlinth);
        }
      }
    } else if (targetY > seatY) {
      // Ground rises: meet the rising terrain
      for (let y = seatY; y <= Math.min(seatY + 2, targetY); y++) {
        if (get(x, y, z) === null) {
          set(x, y, z, stonePlinth);
        }
      }
    }
  }

  // --------------------------------------------------------------------------
  // 9. EMIT BLOCKS
  // --------------------------------------------------------------------------
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "trojan_horse",
    seatY: seatY,
    anchors: {
      front: [7, 26, 0],   // North-facing muzzle
      door: [7, 10, 12],    // Drop ladder ground arrival point
      hatch: [7, 17, 12]    // Belly trapdoor
    },
    interiors: [
      {
        min: [4, 18, 8],
        max: [10, 21, 16],
        kind: "hold"
      }
    ]
  };
}

